namespace ghidra.app.plugin.core.progmgr;








using generic.theme;
using ghidra.framework.data;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.program.database;
using ghidra.program.model.listing;
using ghidra.util;

class TransactionMonitor : JComponent, TransactionListener {

	private static Icon busyIcon;
	private static Dimension prefSize;

	ProgramDB program;
	TransactionInfo lastTx;

	TransactionMonitor() : base()
    {
		busyIcon = new GIcon("icon.plugin.programmanager.busy");
		prefSize = new Dimension(busyIcon.getIconWidth(), busyIcon.getIconHeight());
		ToolTipManager.sharedInstance().registerComponent(this);
	}

	void setProgram(Program p) {
		if (program != null) {
			program.removeTransactionListener(this);
		}
		if (p is ProgramDB) {
			program = (ProgramDB) p;
			program.addTransactionListener(this);
		}
		else {
			program = null;
		}
		lastTx = null;
		repaint();
	}

	/* @Override */
	public void transactionStarted(DomainObjectAdapterDB domainObj, TransactionInfo tx) {
		lastTx = tx;
		repaint();
	}

	/* @Override */
	public void transactionEnded(DomainObjectAdapterDB domainObj) {
		lastTx = null;
		repaint();
	}

	/* @Override */
	public void undoStackChanged(DomainObjectAdapterDB domainObj) {
		// don't care
	}

	/* @Override */
	public void undoRedoOccurred(DomainObjectAdapterDB domainObj) {
		// don't care
	}

	/* @Override */
	public Dimension getPreferredSize() {
		return new Dimension(prefSize);
	}

	/* @Override */
	protected void paintComponent(Graphics g) {
		g.setColor(getBackground());
		g.fillRect(0, 0, getWidth(), getHeight());
		if (lastTx != null) {
			busyIcon.paintIcon(this, g, 0, 0);
		}
	}

	/* @Override */
	public string getToolTipText() {
		if (lastTx != null) {
			List<string> list = lastTx.getOpenSubTransactions();
			StringBuffer tip = new StringBuffer();
			Iterator<string> iter = list.iterator();
			while (iter.hasNext()) {
				if (tip.length() != 0) {
					tip.append('\n');
				}
				tip.append(iter.next());
			}
			return HTMLUtilities.toHTML(tip.toString());
		}
		return null;
	}

}
